import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void max_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int Outer, int Reduce, int Inner)
{
    int outer_idx = blockIdx.x;
    int inner_idx = blockIdx.y * blockDim.x + threadIdx.x;
    if (outer_idx >= Outer || inner_idx >= Inner) return;
    // Direct pointer arithmetic instead of CuTe tensor indexing to avoid
    // recomputing strided offsets on every access inside the hot loop.
    const int64_t base = (int64_t)outer_idx * (int64_t)Reduce * (int64_t)Inner + inner_idx;
    const float* __restrict__ row_ptr = x + base;
    const int64_t stride = (int64_t)Inner;
    float m0 = -FLT_MAX;
    float m1 = -FLT_MAX;
    float m2 = -FLT_MAX;
    float m3 = -FLT_MAX;
    int r = 0;
    #pragma unroll 4
    for (; r + 4 <= Reduce; r += 4) {
        m0 = fmaxf(m0, __ldg(row_ptr + (int64_t)(r + 0) * stride));
        m1 = fmaxf(m1, __ldg(row_ptr + (int64_t)(r + 1) * stride));
        m2 = fmaxf(m2, __ldg(row_ptr + (int64_t)(r + 2) * stride));
        m3 = fmaxf(m3, __ldg(row_ptr + (int64_t)(r + 3) * stride));
    }
    for (; r < Reduce; ++r) {
        m0 = fmaxf(m0, __ldg(row_ptr + (int64_t)r * stride));
    }
    float m = fmaxf(fmaxf(m0, m1), fmaxf(m2, m3));
    out[(int64_t)outer_idx * (int64_t)Inner + inner_idx] = m;
}

torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Expect float32 tensor");

    auto x_c = x.contiguous();
    int64_t ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
    int64_t reduce = x_c.size(dim);
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner *= x_c.size(i);

    // Build output shape (input shape with `dim` removed)
    std::vector<int64_t> out_shape;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_shape.push_back(x_c.size(i));
    }

    auto out = torch::empty(out_shape, x_c.options());

    int Outer = (int)outer;
    int Reduce = (int)reduce;
    int Inner = (int)inner;

    const int threads = 256;
    dim3 block(threads);
    dim3 grid(Outer, (Inner + threads - 1) / threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    max_reduce_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(), out.data_ptr<float>(), Outer, Reduce, Inner);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE max_reduce launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_max_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Max reduction over a specific dimension using a custom CUTE kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_max_reduce(x, self.dim)

